'use client';

import React, { useMemo, useCallback, useRef } from 'react';
import { Stage, Layer } from 'react-konva';
import { Slide, PillarId, SlideContent } from '@/types/index';
import { SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { useDecoratorConfig } from '@/hooks/useDecoratorConfig';
import { useCanvasStore } from '@/store/canvas-store';
import { useCarouselStore } from '@/store/carousel-store';
import { CanvasElement, TextElementData, ImageElementData } from '@/types/canvas-elements';
import { TextElement } from '@/canvas-editor/elements/TextElement';
import { ImageElement } from '@/canvas-editor/elements/ImageElement';
import { BackgroundElement } from '@/canvas-editor/elements/BackgroundElement';
import { DecoratorElement } from '@/canvas-editor/elements/DecoratorElement';
import { CTAElement } from '@/canvas-editor/elements/CTAElement';
import { getDefaultSubTypeForSlideType } from '@/types/slide-subtypes';

interface CanvasSlideProps {
  slide: Slide;
  pillar: PillarId;
  carouselTotalSlides?: number;
  carouselBackgroundPack?: string;
  carouselDecoratorConfig?: any;
  isPreview?: boolean;
  scale?: number;
  onElementsChange?: (elements: CanvasElement[]) => void;
  onElementDelete?: (elementId: string) => void;
}

/**
 * Convert canvas element to slide content
 *
 * Converts a single canvas element update to slide content format.
 * This is used for immediate sync when elements are updated in canvas mode.
 */
function convertCanvasElementToSlideContent(
  element: CanvasElement
): Partial<SlideContent> | null {
  // Only sync text and image elements (background, decorator, CTA are handled separately)
  if (element.type === 'text') {
    const textData = element.data as TextElementData;

    if (element.name === 'Headline') {
      return {
        headline: {
          value: textData.content,
          position: { mode: 'absolute', x: element.x, y: element.y },
        },
      };
    } else if (element.name === 'Subtext') {
      return {
        subtext: {
          value: textData.content,
          position: { mode: 'absolute', x: element.x, y: element.y },
        },
      };
    } else if (element.name === 'Bullets') {
      const bulletLines = textData.content.split('\n');
      const bullets = bulletLines.map(line =>
        line.replace(/^[•\-*]\s*/, '').trim()
      ).filter(line => line.length > 0);

      return {
        bullets: {
          value: bullets,
          position: { mode: 'absolute', x: element.x, y: element.y },
        },
      };
    } else if (element.name === 'Quote') {
      const quoteValue = textData.content.replace(/^"|"$/g, '');
      return {
        quote: {
          value: quoteValue,
          position: { mode: 'absolute', x: element.x, y: element.y },
        },
      };
    } else if (element.name === 'Attribution') {
      const attributionValue = textData.content.replace(/^-\s*/, '');
      return {
        attribution: {
          value: attributionValue,
          position: { mode: 'absolute', x: element.x, y: element.y },
        },
      };
    }
  } else if (element.type === 'image') {
    const imageData = element.data as ImageElementData;

    return {
      imageConfig: {
        imageUrl: imageData.url,
        position: 'half-right',
        size: (element.width / SLIDE_WIDTH) * 100,
        rotation: element.rotation,
        opacity: element.opacity,
        objectFit: imageData.objectFit,
        filters: {
          blur: imageData.filters.blur,
          grayscale: imageData.filters.grayscale,
          sepia: imageData.filters.sepia,
          saturate: imageData.filters.saturate,
          brightness: imageData.filters.brightness,
          contrast: imageData.filters.contrast,
        },
        borderRadius: imageData.borderRadius,
        borderWidth: imageData.borderWidth,
        borderColor: imageData.borderColor,
        shadow: imageData.shadow,
        blendMode: imageData.blendMode as any,
      },
    };
  }

  return null;
}

/**
 * Create canvas elements from slide data
 *
 * This is a simplified version that creates canvas elements directly from slide data
 * without using the deprecated translation layer.
 */
function createCanvasElementsFromSlide(
  slide: Slide,
  pillar: PillarId,
  subTypeConfig: any,
  decoratorConfig: any
): CanvasElement[] {
  const elements: CanvasElement[] = [];
  const content = slide.content;
  const style = slide.style;

  // Helper to get element position
  const getElementPosition = (field: any) => {
    if (field && typeof field === 'object' && 'position' in field) {
      const pos = (field as any).position;
      if (pos && typeof pos === 'object' && 'x' in pos && 'y' in pos) {
        return { x: pos.x, y: pos.y };
      }
    }
    return { x: 0, y: 0 };
  };

  // Helper to get element style
  const getElementStyle = (field: any, defaultStyle: any) => {
    if (field && typeof field === 'object' && 'style' in field) {
      const fieldStyle = (field as any).style;
      if (fieldStyle && typeof fieldStyle === 'object') {
        return { ...defaultStyle, ...fieldStyle };
      }
    }
    return defaultStyle;
  };

  // Create headline element
  if (content.headline && typeof content.headline === 'object' && 'value' in content.headline) {
    const headline = content.headline as any;
    const pos = getElementPosition(headline);
    const theme = require('@/config/pillars').getPillarTheme(pillar);
    const defaultStyle = theme?.headline || { fontSize: 64, color: '#000000', fontWeight: 'bold' };
    const style = getElementStyle(headline, defaultStyle);

    elements.push({
      id: `${slide.id}-headline`,
      type: 'text',
      name: 'Headline',
      x: pos.x,
      y: pos.y,
      width: 800,
      height: 100,
      rotation: 0,
      zIndex: 10,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        content: headline.value,
        fontSize: style.fontSize,
        fontFamily: style.fontFamily || 'Arial',
        fontWeight: style.fontWeight || 'bold',
        color: style.color || '#000000',
        lineHeight: style.lineHeight || 1.2,
        letterSpacing: style.letterSpacing || 0,
      } as TextElementData,
    });
  }

  // Create subtext element
  if (content.subtext && typeof content.subtext === 'object' && 'value' in content.subtext) {
    const subtext = content.subtext as any;
    const pos = getElementPosition(subtext);
    const theme = require('@/config/pillars').getPillarTheme(pillar);
    const defaultStyle = theme?.subtext || { fontSize: 32, color: '#333333', fontWeight: 'normal' };
    const style = getElementStyle(subtext, defaultStyle);

    elements.push({
      id: `${slide.id}-subtext`,
      type: 'text',
      name: 'Subtext',
      x: pos.x,
      y: pos.y,
      width: 800,
      height: 80,
      rotation: 0,
      zIndex: 10,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        content: subtext.value,
        fontSize: style.fontSize,
        fontFamily: style.fontFamily || 'Arial',
        fontWeight: style.fontWeight || 'normal',
        color: style.color || '#333333',
        lineHeight: style.lineHeight || 1.4,
        letterSpacing: style.letterSpacing || 0,
      } as TextElementData,
    });
  }

  // Create bullets element
  if (content.bullets && typeof content.bullets === 'object' && 'value' in content.bullets) {
    const bullets = content.bullets as any;
    const pos = getElementPosition(bullets);
    const theme = require('@/config/pillars').getPillarTheme(pillar);
    const defaultStyle = theme?.bullets || { fontSize: 28, color: '#333333', fontWeight: 'normal' };
    const style = getElementStyle(bullets, defaultStyle);

    elements.push({
      id: `${slide.id}-bullets`,
      type: 'text',
      name: 'Bullets',
      x: pos.x,
      y: pos.y,
      width: 800,
      height: 200,
      rotation: 0,
      zIndex: 10,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        content: Array.isArray(bullets.value) ? bullets.value.join('\n') : bullets.value,
        fontSize: style.fontSize,
        fontFamily: style.fontFamily || 'Arial',
        fontWeight: style.fontWeight || 'normal',
        color: style.color || '#333333',
        lineHeight: style.lineHeight || 1.6,
        letterSpacing: style.letterSpacing || 0,
      } as TextElementData,
    });
  }

  // Create quote element
  if (content.quote && typeof content.quote === 'object' && 'value' in content.quote) {
    const quote = content.quote as any;
    const pos = getElementPosition(quote);
    const theme = require('@/config/pillars').getPillarTheme(pillar);
    const defaultStyle = theme?.quote || { fontSize: 48, color: '#000000', fontWeight: 'normal', fontStyle: 'italic' };
    const style = getElementStyle(quote, defaultStyle);

    elements.push({
      id: `${slide.id}-quote`,
      type: 'text',
      name: 'Quote',
      x: pos.x,
      y: pos.y,
      width: 800,
      height: 150,
      rotation: 0,
      zIndex: 10,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        content: `"${quote.value}"`,
        fontSize: style.fontSize,
        fontFamily: style.fontFamily || 'Georgia',
        fontWeight: style.fontWeight || 'normal',
        color: style.color || '#000000',
        lineHeight: style.lineHeight || 1.4,
        letterSpacing: style.letterSpacing || 0,
        fontStyle: style.fontStyle || 'italic',
      } as TextElementData,
    });
  }

  // Create attribution element
  if (content.attribution && typeof content.attribution === 'object' && 'value' in content.attribution) {
    const attribution = content.attribution as any;
    const pos = getElementPosition(attribution);
    const theme = require('@/config/pillars').getPillarTheme(pillar);
    const defaultStyle = theme?.attribution || { fontSize: 24, color: '#666666', fontWeight: 'normal' };
    const style = getElementStyle(attribution, defaultStyle);

    elements.push({
      id: `${slide.id}-attribution`,
      type: 'text',
      name: 'Attribution',
      x: pos.x,
      y: pos.y,
      width: 800,
      height: 50,
      rotation: 0,
      zIndex: 10,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        content: `- ${attribution.value}`,
        fontSize: style.fontSize,
        fontFamily: style.fontFamily || 'Arial',
        fontWeight: style.fontWeight || 'normal',
        color: style.color || '#666666',
        lineHeight: style.lineHeight || 1.4,
        letterSpacing: style.letterSpacing || 0,
      } as TextElementData,
    });
  }

  // Create image element
  if (content.imageConfig && typeof content.imageConfig === 'object') {
    const imageConfig = content.imageConfig as any;

    elements.push({
      id: `${slide.id}-image`,
      type: 'image',
      name: 'Image',
      x: 800,
      y: 200,
      width: 400,
      height: 400,
      rotation: imageConfig.rotation || 0,
      zIndex: 5,
      locked: false,
      visible: true,
      opacity: imageConfig.opacity || 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        url: imageConfig.imageUrl || '',
        objectFit: imageConfig.objectFit || 'cover',
        filters: {
          blur: imageConfig.filters?.blur || 0,
          grayscale: imageConfig.filters?.grayscale || 0,
          sepia: imageConfig.filters?.sepia || 0,
          saturate: imageConfig.filters?.saturate || 100,
          brightness: imageConfig.filters?.brightness || 100,
          contrast: imageConfig.filters?.contrast || 100,
        },
        borderRadius: imageConfig.borderRadius || 0,
        borderWidth: imageConfig.borderWidth || 0,
        borderColor: imageConfig.borderColor || '#000000',
        shadow: imageConfig.shadow || false,
        blendMode: imageConfig.blendMode || 'normal',
      } as ImageElementData,
    });
  }

  // Create background element
  if (style && 'backgroundColor' in style && style.backgroundColor) {
    elements.push({
      id: `${slide.id}-background`,
      type: 'background',
      name: 'Background',
      x: 0,
      y: 0,
      width: SLIDE_WIDTH,
      height: SLIDE_HEIGHT,
      rotation: 0,
      zIndex: 0,
      locked: true,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        backgroundType: 'solid',
        primaryColor: style.backgroundColor as string,
        opacity: 1,
      },
    });
  }

  // Create decorator element (if enabled)
  if (decoratorConfig?.logo?.enabled) {
    elements.push({
      id: `${slide.id}-decorator-logo`,
      type: 'decorator',
      name: 'Logo',
      x: decoratorConfig.logo.position === 'top-right' ? SLIDE_WIDTH - 100 : 20,
      y: 20,
      width: decoratorConfig.logo.size || 80,
      height: decoratorConfig.logo.size || 80,
      rotation: 0,
      zIndex: 20,
      locked: true,
      visible: true,
      opacity: decoratorConfig.logo.opacity || 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        decoratorType: 'logo',
        url: decoratorConfig.logo.imageUrl || '/default-logo.png',
      } as any,
    });
  }

  // Create CTA element (if exists)
  if (slide.cta && typeof slide.cta === 'object' && 'text' in slide.cta && slide.cta.text) {
    const cta = slide.cta as any;
    elements.push({
      id: `${slide.id}-cta`,
      type: 'cta',
      name: 'CTA',
      x: 100,
      y: 700,
      width: 300,
      height: 60,
      rotation: 0,
      zIndex: 15,
      locked: false,
      visible: true,
      opacity: 1,
      scaleX: 1,
      scaleY: 1,
      data: {
        text: cta.text || 'Learn More',
        style: cta.style || 'solid',
        shape: cta.shape || 'pill',
        backgroundColor: cta.backgroundColor || '#00E5FF',
        textColor: cta.textColor || '#000000',
        borderRadius: cta.borderRadius || 8,
        shadow: cta.shadow || true,
      } as any,
    });
  }

  return elements;
}

/**
 * CanvasSlide - Canvas-based slide rendering component
 *
 * Phase 4 Refactor: Simplified Architecture
 *
 * This component renders a slide using Konva canvas without the deprecated translation layer.
 * Elements are created directly from slide data using simplified functions.
 *
 * Features:
 * - Direct element creation from slide data (no translation layer)
 * - Renders all element types (text, image, background, decorator, CTA)
 * - Supports all slide types (title, content, bullets, quote, cta, image)
 * - Maintains pillar theme styling
 * - Supports background packs
 * - Supports decorator configuration
 * - Single source of truth (carousel-store)
 * - Comprehensive error handling
 */
export const CanvasSlide: React.FC<CanvasSlideProps> = ({
  slide,
  pillar,
  carouselTotalSlides,
  carouselBackgroundPack,
  carouselDecoratorConfig,
  isPreview = false,
  scale = 1,
  onElementsChange,
  onElementDelete,
}) => {
  // Edge Case: Missing slide data
  if (!slide) {
    console.error('[CanvasSlide] No slide data provided');
    return (
      <div className="flex items-center justify-center w-full h-full bg-gray-100 text-gray-500">
        <div className="text-center">
          <p className="text-lg font-semibold">No slide data</p>
          <p className="text-sm">Please select a slide to edit</p>
        </div>
      </div>
    );
  }

  // Edge Case: Invalid slide ID
  if (!slide.id) {
    console.error('[CanvasSlide] Slide missing ID:', slide);
    return (
      <div className="flex items-center justify-center w-full h-full bg-red-50 text-red-500">
        <div className="text-center">
          <p className="text-lg font-semibold">Invalid slide data</p>
          <p className="text-sm">Slide is missing required ID</p>
        </div>
      </div>
    );
  }

  // Store updateSlide in ref to keep dependency array stable
  const { updateSlide } = useCarouselStore();
  const updateSlideRef = useRef(updateSlide);
  updateSlideRef.current = updateSlide;

  // Get selection state from canvas store (UI state only)
  const { selectedIds } = useCanvasStore();

  // Track local element state (for rendering)
  const localElementsRef = useRef<Map<string, Partial<CanvasElement>>>(new Map());

  // Get sub-type configuration
  const { getSubType } = require('@/config/slide-subtypes');
  const subTypeConfig = getSubType(slide.subType || getDefaultSubTypeForSlideType(slide.type));

  // Use unified decorator config system
  const { config: decoratorConfig } = useDecoratorConfig({
    carouselConfig: carouselDecoratorConfig,
    pillarId: pillar,
    slideConfig: slide.style?.decoratorConfig,
    styleTemplateId: slide.style?.template,
    applyTemplateSuggestions: true,
  });

  // Create canvas elements from slide data (simplified, no translation layer)
  const computedElements = useMemo(() => {
    try {
      return createCanvasElementsFromSlide(slide, pillar, subTypeConfig, decoratorConfig);
    } catch (error) {
      console.error('[CanvasSlide] Element creation failed:', error);
      return [];
    }
  }, [slide, pillar, subTypeConfig, decoratorConfig]);

  // Merge computed elements with local modifications
  const elements = useMemo(() => {
    const merged = new Map<string, CanvasElement>();

    // Start with computed elements
    computedElements.forEach((element) => {
      if (!element || !element.id || !element.type) {
        console.warn('[CanvasSlide] Skipping invalid element:', element);
        return;
      }
      merged.set(element.id, element);
    });

    // Apply local modifications (user edits)
    localElementsRef.current.forEach((element, id) => {
      if (merged.has(id)) {
        merged.set(id, { ...merged.get(id)!, ...element });
      }
    });

    // Expose elements to parent
    if (onElementsChange) {
      const elementsArray = Array.from(merged.values());
      onElementsChange(elementsArray);
    }

    return merged;
  }, [computedElements, onElementsChange]);

  // Handle element update (writes to carousel-store)
  const handleElementUpdate = useCallback((elementId: string, updates: Partial<CanvasElement>) => {
    console.log('[CanvasSlide] Element update:', elementId, updates);

    if (!elementId) {
      console.warn('[CanvasSlide] Element update called with invalid element ID');
      return;
    }

    // Update local state (for immediate feedback)
    const existingUpdate = localElementsRef.current.get(elementId) || {};
    localElementsRef.current.set(elementId, { ...existingUpdate, ...updates } as Partial<CanvasElement>);

    const element = elements.get(elementId);
    if (!element) {
      console.warn('[CanvasSlide] Element not found:', elementId);
      return;
    }

    if (isPreview) {
      console.log('[CanvasSlide] Skipping update in preview mode');
      return;
    }

    if (!updates || Object.keys(updates).length === 0) {
      console.warn('[CanvasSlide] Skipping empty update');
      return;
    }

    try {
      const updatedElement = { ...element, ...updates };
      const slideContent = convertCanvasElementToSlideContent(updatedElement);

      if (slideContent) {
        console.log('[CanvasSlide] Writing to carousel-store:', slide.id, slideContent);
        updateSlideRef.current(slide.id, slideContent);
      }
    } catch (error) {
      console.error('[CanvasSlide] Error updating slide:', error);
    }
  }, [elements, slide.id, isPreview]);

  // Handle element deletion
  const handleElementDelete = useCallback((elementId: string) => {
    console.log('[CanvasSlide] Element delete:', elementId);

    if (!elementId) {
      console.warn('[CanvasSlide] Element delete called with invalid element ID');
      return;
    }

    if (isPreview) {
      console.log('[CanvasSlide] Skipping delete in preview mode');
      return;
    }

    const element = elements.get(elementId);
    if (!element) {
      console.warn('[CanvasSlide] Element not found for deletion:', elementId);
      return;
    }

    const contentFieldMap: Record<string, keyof SlideContent> = {
      'Headline': 'headline',
      'Subtext': 'subtext',
      'Bullets': 'bullets',
      'Quote': 'quote',
      'Attribution': 'attribution',
    };

    const field = contentFieldMap[element.name];
    if (field) {
      updateSlideRef.current(slide.id, { [field]: undefined });
    } else {
      console.warn('[CanvasSlide] Cannot delete element type:', element.name);
    }

    if (onElementDelete) {
      onElementDelete(elementId);
    }
  }, [elements, slide.id, isPreview, onElementDelete]);

  // Get sorted elements by zIndex
  const sortedElements = Array.from(elements.values()).sort((a, b) => a.zIndex - b.zIndex);

  // Handle element selection
  const handleElementSelect = useCallback((elementId: string) => {
    if (!isPreview) {
      const { selectElement } = useCanvasStore.getState();
      selectElement(elementId, false);
    }
  }, [isPreview]);

  // Handle element transform
  const handleElementTransform = useCallback((elementId: string) => (transform: any) => {
    console.log('[CanvasSlide] Transform called for', elementId, ':', transform);
    handleElementUpdate(elementId, transform);
  }, [handleElementUpdate]);

  // Render element based on type
  const renderElement = (element: CanvasElement) => {
    if (!element || !element.id || !element.type) {
      console.warn('[CanvasSlide] Skipping invalid element in render:', element);
      return null;
    }

    const isSelected = selectedIds.includes(element.id);
    const onSelect = handleElementSelect;
    const onTransform = handleElementTransform(element.id);

    try {
      switch (element.type) {
        case 'text':
          return (
            <TextElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );
        case 'image':
          return (
            <ImageElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );
        case 'background':
          return (
            <BackgroundElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );
        case 'decorator':
          return (
            <DecoratorElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );
        case 'cta':
          return (
            <CTAElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );
        default:
          console.warn(`[CanvasSlide] Unknown element type: ${element.type}`);
          return null;
      }
    } catch (error) {
      console.error(`[CanvasSlide] Error rendering element ${element.id}:`, error);
      return null;
    }
  };

  // Edge Case: Empty slide (no elements)
  if (sortedElements.length === 0) {
    return (
      <Stage
        width={SLIDE_WIDTH * scale}
        height={SLIDE_HEIGHT * scale}
        scaleX={scale}
        scaleY={scale}
        className="canvas-slide"
      >
        <Layer>
          <div className="flex items-center justify-center w-full h-full text-gray-400 text-sm">
            <p>No elements to display</p>
          </div>
        </Layer>
      </Stage>
    );
  }

  return (
    <Stage
      width={SLIDE_WIDTH * scale}
      height={SLIDE_HEIGHT * scale}
      scaleX={scale}
      scaleY={scale}
      className="canvas-slide"
    >
      <Layer>
        {sortedElements.map((element: CanvasElement) => renderElement(element))}
      </Layer>
    </Stage>
  );
};

